# report-v3.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$defs": {
    "column": {
      "additionalProperties": false,
      "properties": {
        "name": {
          "pattern": "^[a-z][a-z0-9_]*$",
          "type": "string"
        },
        "nullable": {
          "type": "boolean"
        },
        "type": {
          "enum": [
            "string",
            "integer",
            "number",
            "boolean",
            "timestamp",
            "json"
          ]
        }
      },
      "required": [
        "name",
        "type",
        "nullable"
      ],
      "type": "object"
    },
    "dataset": {
      "additionalProperties": false,
      "properties": {
        "class": {
          "const": "dataset"
        },
        "columns": {
          "items": {
            "$ref": "#/$defs/column"
          },
          "minItems": 1,
          "type": "array"
        },
        "dataset_id": {
          "pattern": "^ds-[0-9]{8}-[0-9]{4}-[a-z0-9]+$",
          "type": "string"
        },
        "query_contract": {
          "additionalProperties": false,
          "properties": {
            "cursor_field": {
              "minLength": 1,
              "type": "string"
            },
            "filter": {
              "minLength": 1,
              "type": "string"
            },
            "order_by": {
              "minLength": 1,
              "type": "string"
            },
            "page_size": {
              "maximum": 500,
              "minimum": 1,
              "type": "integer"
            }
          },
          "required": [
            "filter",
            "order_by",
            "page_size",
            "cursor_field"
          ],
          "type": "object"
        },
        "rows": {
          "items": {
            "$ref": "#/$defs/dataset_row"
          },
          "minItems": 2,
          "type": "array"
        },
        "schema_ref": {
          "$ref": "#/$defs/schema_ref"
        }
      },
      "required": [
        "class",
        "dataset_id",
        "schema_ref",
        "columns",
        "rows",
        "query_contract"
      ],
      "type": "object"
    },
    "dataset_row": {
      "additionalProperties": false,
      "properties": {
        "row_id": {
          "pattern": "^r[0-9]{8}$",
          "type": "string"
        },
        "row_ts": {
          "format": "date-time",
          "type": [
            "string",
            "null"
          ]
        },
        "values": {
          "minProperties": 1,
          "type": "object"
        }
      },
      "required": [
        "row_id",
        "values"
      ],
      "type": "object"
    },
    "digest": {
      "pattern": "^sha256:[0-9a-f]{64}$",
      "type": "string"
    },
    "envelope": {
      "additionalProperties": false,
      "properties": {
        "agent_ts": {
          "format": "date-time",
          "type": [
            "string",
            "null"
          ]
        },
        "artifacts": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "assignment": {
          "additionalProperties": false,
          "properties": {
            "completion_policy": {
              "enum": [
                "manager_reported",
                "director_acceptance",
                "objective_acceptance"
              ]
            },
            "required_content": {
              "enum": [
                "free_form",
                "structured",
                "dataset"
              ]
            },
            "schema_ref": {
              "anyOf": [
                {
                  "$ref": "#/$defs/schema_ref"
                },
                {
                  "type": "null"
                }
              ]
            },
            "validation_policy": {
              "enum": [
                "none",
                "json_schema",
                "dataset_columns"
              ]
            }
          },
          "required": [
            "required_content",
            "validation_policy",
            "completion_policy"
          ],
          "type": "object"
        },
        "attempt_id": {
          "pattern": "^at-[0-9]{8}-[0-9]{4}-[a-z0-9]+$",
          "type": "string"
        },
        "content_digest": {
          "$ref": "#/$defs/digest"
        },
        "content_ref": {
          "pattern": "^/chd/(room|report)/.+$",
          "type": "string"
        },
        "criteria_results": {
          "items": {
            "type": "object"
          },
          "type": "array"
        },
        "id": {
          "pattern": "^r-[0-9]{8}-[0-9]{4}-[a-z0-9]+$",
          "type": "string"
        },
        "ingest_ts": {
          "format": "date-time",
          "type": "string"
        },
        "next": {
          "type": [
            "string",
            "null"
          ]
        },
        "produced_by": {
          "minLength": 1,
          "type": "string"
        },
        "reason": {
          "type": [
            "string",
            "null"
          ]
        },
        "request_ref": {
          "pattern": "^/chd/room/.+/m[0-9]{12}$",
          "type": "string"
        },
        "room": {
          "minLength": 1,
          "type": "string"
        },
        "send_id": {
          "pattern": "^s-[0-9]{8}-[0-9]{4}-[a-z0-9]+$",
          "type": "string"
        },
        "session_ref": {
          "additionalProperties": false,
          "properties": {
            "mode": {
              "enum": [
                "NEW",
                "REUSE"
              ]
            },
            "session_key": {
              "minLength": 1,
              "type": "string"
            }
          },
          "required": [
            "mode",
            "session_key"
          ],
          "type": "object"
        },
        "status": {
          "enum": [
            "done",
            "deferred",
            "blocked",
            "failed",
            "waiting_human"
          ]
        },
        "summary": {
          "minLength": 1,
          "type": "string"
        },
        "waiting_for_human": {
          "type": [
            "object",
            "null"
          ]
        }
      },
      "required": [
        "id",
        "produced_by",
        "room",
        "send_id",
        "attempt_id",
        "request_ref",
        "session_ref",
        "status",
        "summary",
        "assignment",
        "content_ref",
        "content_digest",
        "ingest_ts"
      ],
      "type": "object"
    },
    "free_form": {
      "additionalProperties": false,
      "properties": {
        "class": {
          "const": "free_form"
        },
        "text": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "class",
        "text"
      ],
      "type": "object"
    },
    "id": {
      "pattern": "^[a-z][a-z0-9_-]{0,63}$",
      "type": "string"
    },
    "schema_ref": {
      "additionalProperties": false,
      "properties": {
        "digest": {
          "$ref": "#/$defs/digest"
        },
        "name": {
          "minLength": 1,
          "type": "string"
        },
        "version": {
          "pattern": "^[0-9]+\\.[0-9]+$",
          "type": "string"
        }
      },
      "required": [
        "name",
        "version",
        "digest"
      ],
      "type": "object"
    },
    "structured": {
      "additionalProperties": false,
      "properties": {
        "class": {
          "const": "structured"
        },
        "schema_ref": {
          "$ref": "#/$defs/schema_ref"
        },
        "value": {
          "minProperties": 1,
          "type": "object"
        }
      },
      "required": [
        "class",
        "schema_ref",
        "value"
      ],
      "type": "object"
    }
  },
  "$id": "https://coding-hermes.example/contracts/report-v3.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "content": {
      "oneOf": [
        {
          "$ref": "#/$defs/free_form"
        },
        {
          "$ref": "#/$defs/structured"
        },
        {
          "$ref": "#/$defs/dataset"
        }
      ]
    },
    "envelope": {
      "$ref": "#/$defs/envelope"
    },
    "schema_version": {
      "const": 3
    }
  },
  "required": [
    "schema_version",
    "envelope",
    "content"
  ],
  "title": "CHD report envelope v3",
  "type": "object"
}
```
